def comps_val(G,val,conn=4):
 h,w=len(G),len(G[0]); ds=[(-1,0),(1,0),(0,-1),(0,1)] if conn==4 else [(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc)!=(0,0)]
 seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if G[r][c]==val and (r,c) not in seen:
    q=deque([(r,c)]); seen.add((r,c)); cc=[]
    while q:
     a,b=q.popleft();cc.append((a,b))
     for dr,dc in ds:
      x,y=a+dr,b+dc
      if 0<=x<h and 0<=y<w and G[x][y]==val and (x,y) not in seen:
       seen.add((x,y));q.append((x,y))
    out.append(cc)
 return out
